Lombok es una biblioteca Java que nos permite reemplazar las líneas de código que creamos para los constructores, getter y setter, entre otros, por unas simple anotaciones, por lo que cuando creamos una clase solo definimos las propiedades y ésta librería hace el resto.
Con una simple anotación(@Data), Lombok inyectará los métodos getter y setter para cada propiedad, además de un equals, hashCode y toString.
https://1.bp.blogspot.com/–CYarvynlTU/Xp24u-wh6zI/AAAAAAAAAKE/-pW3SGJ7qokEtPL93HgN911_hjvzZCnnQCLcBGAsYHQ/s400/28ae0b5bfcf57c9972db8ecc6f9df091_f652.png @Getter y Setter Se usan para generar un getter y setter para un atributo específico.
/*BEFORE*/ public boolean isEmployed() { return employed; } public void setEmployed(final boolean employed) { this.employed = employed; } /*AFTER*/ @Getter @Setter private boolean employed; @NonNull Cuando se coloca en un atributo para el que Lombok está generando un método de establecimiento, se generará una comprabación que dará como resultado un NullPointerException, si se proporciona un valor nulo.
/*BEFORE*/ public class Family{ private List&lt;Person&gt; members; public Family(List&lt;Person&gt; members) { if (members == null) throw new java.lang.NullPointerException(&#34;members&#34;); this.members = members; } public void setMembers(List&lt;Person&gt; members) { if (members == null) throw new java.lang.NullPointerException(&#34;members&#34;); this.members = members; } } /*AFTER*/ @Setter @NonNull private List&lt;Person&gt; members; @ToString Genera una implementación del método toString. Imprimirá todos los atributos en forma de clave-valor, para todos los campos que no sean estáticos. Podemos personalizar su funcionamiento mediante los siguientes parámetros:
includeFieldNames = false → No incluye el nombre de los atributos (clave) exclude=&ldquo;nombreDeAtributo&rdquo; → No incluye el atributo especificado of → Lista de atributos a imprimir callSuper = true → Junta el toString de la clase actual con el de la clase de la que extiende /*BEFORE*/ public class Foo extends Bar { private boolean someBoolean = true; private String someStringField; private float someExcludedField; @java.lang.Override public java.lang.String toString() { return &#34;Foo(super=&#34; + super.toString() + &#34;, someBoolean=&#34; + someBoolean + &#34;, someStringField=&#34; + someStringField + &#34;)&#34;; } } /*AFTER*/ @ToString(callSuper=true,exclude=&#34;someExcludedField&#34;) public class Foo extends Bar { private boolean someBoolean = true; private String someStringField; private float someExcludedField; } @EQUALSANDHASHCODE Generará una implementación de los métodos equals y hashCode, para comparar un objeto de la clase con otro. Le podemos especificar una serie de parámetros:
exclude=&ldquo;nombreDeAtributo&rdquo; → No compara por el atributo especificado of → Lista de atributos a comparar callSuper = true → Compara también por la clase de la que extiende /*BEFORE*/ public class Person extends SentientBeing { enum Gender { /*public static final*/ Male /* = new Gender() */, /*public static final*/ Female /* = new Gender() */; } @NonNull private String name; @NonNull private Gender gender; private String ssn; private String address; private String city; private String state; private String zip; @java.lang.Override public boolean equals(final java.lang.Object o) { if (o == this) return true; if (o == null) return false; if (o.getClass() != this.getClass()) return false; if (!super.equals(o)) return false; final Person other = (Person)o; if (this.name == null ? other.name != null : !this.name.equals(other.name)) return false; if (this.gender == null ? other.gender != null : !this.gender.equals(other.gender)) return false; if (this.ssn == null ? other.ssn != null : !this.ssn.equals(other.ssn)) return false; return true; } @java.lang.Override public int hashCode() { final int PRIME = 31; int result = 1; result = result * PRIME + super.hashCode(); result = result * PRIME + (this.name == null ? 0 : this.name.hashCode()); result = result * PRIME + (this.gender == null ? 0 : this.gender.hashCode()); result = result * PRIME + (this.ssn == null ? 0 : this.ssn.hashCode()); return result; } } /*AFTER*/ @EqualsAndHashCode(callSuper=true,exclude={&#34;address&#34;,&#34;city&#34;,&#34;state&#34;,&#34;zip&#34;}) public class Person extends SentientBeing { enum Gender { Male, Female } @NonNull private String name; @NonNull private Gender gender; private String ssn; private String address; private String city; private String state; private String zip; } @Data Combina la funcionalidad de @ToString, @EqualsAndHashCode, @Getter, y @Setter, todo lo que un Plain Old Java Object (POJO) necesita. También se le pueden especificar parámetros como:
staticConstructor = &ldquo;metodoFactoria&rdquo; → El constructor se vuelve privado y se crea un método factoría con el nombre especificado. /*BEFORE*/ public class Company { private final Person founder; private String name; private List&lt;Person&gt; employees; private Company(final Person founder) { this.founder = founder; } public static Company of(final Person founder) { return new Company(founder); } public Person getFounder() { return founder; } public String getName() { return name; } public void setName(final String name) { this.name = name; } public List&lt;Person&gt; getEmployees() { return employees; } public void setEmployees(final List&lt;Person&gt; employees) { this.employees = employees; } @java.lang.Override public boolean equals(final java.lang.Object o) { if (o == this) return true; if (o == null) return false; if (o.getClass() != this.getClass()) return false; final Company other = (Company)o; if (this.founder == null ? other.founder != null : !this.founder.equals(other.founder)) return false; if (this.name == null ? other.name != null : !this.name.equals(other.name)) return false; if (this.employees == null ? other.employees != null : !this.employees.equals(other.employees)) return false; return true; } @java.lang.Override public int hashCode() { final int PRIME = 31; int result = 1; result = result * PRIME + (this.founder == null ? 0 : this.founder.hashCode()); result = result * PRIME + (this.name == null ? 0 : this.name.hashCode()); result = result * PRIME + (this.employees == null ? 0 : this.employees.hashCode()); return result; } @java.lang.Override public java.lang.String toString() { return &#34;Company(founder=&#34; + founder + &#34;, name=&#34; + name + &#34;, employees=&#34; + employees + &#34;)&#34;; } } /*AFTER*/ @Data(staticConstructor=&#34;of&#34;) public class Company { private final Person founder; private String name; private List&lt;Person&gt; employees; } @Builder Usaremos el patrón Builder sin necesidad de implementar código para ello, bastante útil también en la ejecución de test (unit test por ejemplo) en donde debemos crear el objeto con atributos válidos o por defecto.
@Getter @Builder public class Widget { private final String name; private final int id; } /************************************/ Widget testWidget = Widget.builder() .name(&#34;foo&#34;) .id(1) .build(); assertThat(testWidget.getName()) .isEqualTo(&#34;foo&#34;); assertThat(testWidget.getId()) .isEqualTo(1);

Inicio Arrancando con un proyecto Para crear un proyecto de una forma rápida y sencilla he encontrado Spring Initializr. Es muy simple, basta con elegir lenguaje, versión y otras configuraciones, como los metadatos del proyecto, y finalmente las dependencias del proyecto Spring que usaremos.
Si elegimos &ldquo;generar&rdquo; nos descarga un archivo zip que cual contiene el proyecto creado ya preparado para empezar a trabajar con él.
Estructura de un proyecto En el archivo pom.xml tenemos la configuración que realizamos en Spring Initializr.
En src → main → Java → com.example.demo, tenemos una clase DemoApplication que tiene un método main con algo de código, que nos servirá para comprobar que todo está bien y que nuestro proyecto está preparado para ser usado.
En src → main → Resources, tenemos dos carpetas para guardar archivos para nuestra aplicación web, como plantillas.
Inyección de dependencias Repositorios Por convención para guardar datos se usan los repositorios. A la clase que definamos como repositorio le añadimos la anotación &ldquo;@Repository&rdquo; para que el framework entienda que se usara dicha clase como la capa de repositorio.
@Repository public class PersonaRepositoryImpl implements PersonaRepository { private static Logger LOG = LoggerFactory.getLogger(PruebaSpringBootApplication.class); @Override public void registrar(String nombre) { LOG.info(&#34;SE REGISTRO A &#34;+ nombre); } } Servicios Es la capa de lógica de negocio. La clase debe llevar la anotación &ldquo;@Service&rdquo; para indicar que funcionará como la capa de negocio. Si ponemos el ejemplo de que éste servicio actúa sobre un repositorio, podemos crear una instancia del repositorio con la etiqueta &ldquo;@Autowired&rdquo;, para que sea el propio Spring quien se encargue de crear una instancia de la clase.
@Service public class PersonaServiceImpl implements PersonaService { @Autowired private PersonaRepository repo; @Override public void registrar(String nombre) { repo.registrar(nombre); } } Qualifier Para tener varias implementaciones de una interfaz usaremos la etiqueta &ldquo;@Qualifier&rdquo;. En éste ejemplo tenemos dos tipos de personas (repositorios), y después desde un servicio accederemos a uno de los repos con la misma anotación.
@Repository @Qualifier(&#34;persona1&#34;) public class PersonaRepositoryImpl implements PersonaRepository { private static Logger LOG = LoggerFactory.getLogger(PruebaSpringBootApplication.class); @Override public void registrar(String nombre) { LOG.info(&#34;SE REGISTRO A &#34;+ nombre); } } /**************************************************************************************/ @Repository @Qualifier(&#34;persona2&#34;) public class PersonaRepositoryImpl2 implements PersonaRepository { private static Logger LOG = LoggerFactory.getLogger(PruebaSpringBootApplication.class); @Override public void registrar(String nombre) { LOG.info(&#34;SE REGISTRO A &#34;+ nombre + &#34;(persona2)&#34;); } } /**************************************************************************************/ @Service public class PersonaServiceImpl implements PersonaService { @Autowired @Qualifier(&#34;persona2&#34;) private PersonaRepository repo; @Override public void registrar(String nombre) { repo.registrar(nombre); } } Spring Data (JPA) Vamos a crear una aplicación que se conecte a una base de datos usando JPA, un módulo que facilita la implementación de repositorios basados en JPA. Creamos una carpeta &ldquo;modelos&rdquo; y dentro una clase que definirá el modelo de nuestra tabla en la BD.
Persona.java
@Entity public class Persona { @Id private int idPersona; @Column(name = &#34;nombre&#34;,length = 50) private String nombre; public int getIdPersona() { return idPersona; } public void setIdPersona(int idPersona) { this.idPersona = idPersona; } public String getNombre() { return nombre; } public void setNombre(String nombre) { this.nombre = nombre; } } Después, creamos dentro de &ldquo;repositorios&rdquo; una interfaz que extienda de &ldquo;JpaRepository&rdquo;.
IPersonaRepositorio.java
public interface IPersonaRepositorio extends JpaRepository&lt;Persona,Integer&gt; { } Es necesario que el archivo application.properties tenga configurado lo siguiente:
spring.jpa.database=POSTGRESQL spring.jpa.show-sql=true spring.jpa.hibernate.ddl-auto=update spring.datasource.driver-class-name=org.postgresql.Driver spring.datasource.url=jdbc:postgresql://localhost/Welcome spring.datasource.username=postgresql spring.datasource.password=passwword spring.jpa.properties.hibernate.jdbc.lob.non_contextual_creation=true El siguiente paso es crear la base de datos desde pgAdmin 4 (Postgresql), y ejecutar la aplicación para que se nos cree la estructura de tablas.
Para que se nos cree una tabla en la BD y meter datos dentro de ésta, definiremos nuestro método para insertar datos a la tabla.
WelcomeController.java
@Autowired private IPersonaRepositorio repositorio; @GetMapping(&#34;/welcome&#34;) public String welcome(@RequestParam(name=&#34;name&#34;,required = false,defaultValue = &#34;suso&#34;) String name, Model model) { Persona p = new Persona(); p.setIdPersona((int) repositorio.count()); p.setNombre(name); repositorio.save(p); model.addAttribute(&#34;name&#34;, name); return &#34;welcome&#34;; } Tendremos otro método que listara todo el contenido de la tabla. Le crearemos una plantilla para mostrar los datos guardados en el modelo.
WelcomeController.java
@GetMapping(&#34;/listar&#34;) public String todasLasPersonas(Model model) { model.addAttribute(&#34;personas&#34;,repositorio.findAll()); return &#34;personas&#34;; } Ahora nos queda recorrer en la vista la lista de personas guardadas en el Model.
Personas.html
&lt;!DOCTYPE html&gt; &lt;html lang=&#34;en&#34; xmlns:th=&#34;&lt;http://www.thymeleaf.org&gt;&#34;&gt; &lt;head&gt; &lt;meta charset=&#34;UTF-8&#34;&gt; &lt;title&gt;Title&lt;/title&gt; &lt;/head&gt; &lt;body&gt; &lt;table&gt; &lt;th:block th:each=&#34;persona : ${personas}&#34;&gt; &lt;tr&gt; &lt;td th:text=&#34;${persona.idPersona}&#34;&gt;&lt;/td&gt; &lt;td th:text=&#34;${persona.nombre}&#34;&gt;&lt;/td&gt; &lt;/tr&gt; &lt;/th:block&gt; &lt;/table&gt; &lt;/body&gt; &lt;/html&gt; Servicios Rest (CRUD) Se usa para describir cualquier interfaz entre sistemas que utilice directamente HTTP para obtener datos o indicar la ejecución de operaciones sobre los datos en cualquier formato (XML, JSON, etc).
Para crear un controlador que utilice los servicios Rest utilizamos la anotación &ldquo;@RestController&rdquo;.
Método Get Si queremos definir la operación get, usaremos &ldquo;@GetMapping&rdquo;.
Método Post Si queremos definir la operación Post, usaremos &ldquo;@PostMapping&rdquo;. Es necesario pasar como parámetro &ldquo;@RequestBody Objeto o&rdquo;.
Método Put Si queremos definir la operación Put, usaremos &ldquo;@PutMapping&rdquo;. Funciona igual que el Post, pero con la diferencia de que si encuentra un id ya existente la operación será una actualización.
Método Delete Si queremos definir la operación Delete, usaremos &ldquo;@DeleteMapping&rdquo;, que llevar como parámetro el valor (id) que se recoge en la ruta. En el argumento del método, recogemos el id mediante &ldquo;@PathVariable(id)&rdquo;
RestDemoController.java
@RestController public class RestDemoController { @Autowired private IPersonaRepositorio repositorio; @GetMapping public List&lt;Persona&gt; listar(){ return repositorio.findAll(); } @PostMapping public void insertar(@RequestBody Persona persona){ repositorio.save(persona); } @PutMapping public void modificar(@RequestBody Persona persona){ repositorio.save(persona); } @DeleteMapping(value = &#34;/{id}&#34;) public void eliminar(@PathVariable(&#34;id&#34;) Integer id){ repositorio.deleteById(id); } } MVC Thymeleaf Controladores Por un lado tenemos los controladores, anotamos la clase mediante &ldquo;@Controller&rdquo;. Los métodos que se desea que funcionen como ruta de nuestra aplicación web, debe tener la anotación &ldquo;@GetMapping(&lsquo;ruta_a_elegir&rsquo;)&rdquo;.
@Controller public class MainController { @GetMapping(&#34;/welcome&#34;) public String welcome(@RequestParam(name=&#34;name&#34;,required = false,defaultValue = &#34;suso&#34;) String name, Model model){ model.addAttribute(&#34;name&#34;,name); return &#34;Welcome&#34;; } } Si se pasa parámetro en la ruta, se recoge mediante &ldquo;@RequestParam&rdquo; en éste caso en la variable name(String) y se guarda en la variable model(Model), la cual lo usamos para pasar datos a las vistas.
Vistas Para crear las vistas añadimos nuestras páginas html en la carpeta &ldquo;Templates&rdquo;.
El controlador debe indicar en el return el nombre de la vista a la que se dirige.
Necesitamos referenciar en la etiqueta html el motor de plantillas de thymeleaf (xmlns:th=&quot;http://www.thymeleaf.org&quot;). Para incrustar texto en una etiqueta usando dicho motor, usamos &ldquo;th:text&rdquo;, al cual le podemos indicar una variable guardada en el objeto model con &ldquo;${variable}&rdquo;.
&lt;!DOCTYPE html&gt; &lt;html lang=&#34;en&#34; xmlns:th=&#34;&lt;http://www.thymeleaf.org&gt;&#34;&gt; &lt;head&gt; &lt;meta charset=&#34;UTF-8&#34;&gt; &lt;title&gt;Title&lt;/title&gt; &lt;/head&gt; &lt;body&gt; &lt;p th:text=&#34;&#39;Bienvenido, &#39;+${name}&#34;/&gt; &lt;/body&gt; &lt;/html&gt; Spring security Éstas dependencias nos crearán automáticamente un login para nuestra aplicación web, en el que podemos editar el usuario y contraseña de la siguiente manera en el archivo application.properties spring.security.user.name = pady spring.security.user.password= 1234 Es un ejemplo poco práctico, ya que lo óptimo sería comprobar los usuarios mediante una base de datos. Creamos la clase usuario y su repositorio.
Usuario.java
@Entity public class Usuario { @Id private int id; private String nombre; private String clave; public int getId() { return id; } public void setId(int id) { this.id = id; } public String getNombre() { return nombre; } public void setNombre(String nombre) { this.nombre = nombre; } public String getClave() { return clave; } public void setClave(String clave) { this.clave = clave; } } IUsuarioRepositorio.java
public interface IUsuarioRepositorio extends JpaRepository&lt;Usuario,Integer&gt; { } Agregamos nuestro usuario a la tabla
SpringDataApplicationTests.java
@Autowired private IUsuarioRepositorio repositorio_usuarios; @Test void crearUsuario() { Usuario usuario = new Usuario(); usuario.setId(0); usuario.setClave(&#34;1234&#34;); usuario.setNombre(&#34;pady&#34;); Usuario actual = repositorio_usuarios.save(usuario); assertEquals(&#34;1234&#34;,actual.getClave()); } Vamos a crear una clase de configuración en nuestro proyecto, en la que usaremos un @Bean de Spring para cifrar las contraseñas que se guardan en la base datos.
SecurityConfig.java
@Configuration public class SecurityConfig { @Bean public BCryptPasswordEncoder passwordEncoder(){ BCryptPasswordEncoder bCryptPasswordEncoder = new BCryptPasswordEncoder(); return bCryptPasswordEncoder; } } Finalmente lo instanciamos en la clase donde interese, y usamos su método encode.
SpringDataApplicationTests.java
@Autowired private BCryptPasswordEncoder encoder; @Test void crearUsuario() { Usuario usuario = new Usuario(); usuario.setId(1); usuario.setClave(encoder.encode(&#34;1234&#34;)); String expected = usuario.getClave(); usuario.setNombre(&#34;pady&#34;); Usuario actual = repositorio_usuarios.save(usuario); assertEquals(expected,actual.getClave()); } Para habilitar @WebSecurity necesitamos que nuestra clase de configuración extienda de WebSecurityConfigureAdapter . Sobreescibrimos los métodos configure para indicar de donde sacaremos los usuarios a comparar. Pero primero debemos crear una clase UserService que extienda de UserDetailsService , en la cual instanciamos el repositorio de usuarios, y sobrescribimos el método de la clase extendida. Para configurar el método de la clase extendida, tenemos que tener un método que busque por un nombre de usuario, y no por un id, así que vamos a la interfaz repositorio de usuarios y creamos dicho método.
IUsuarioRepositorio.java
public interface IUsuarioRepositorio extends JpaRepository&lt;Usuario,Integer&gt; { Usuario findByNombre(String nombre); } UserService.java
@Service public class UserService implements UserDetailsService { @Autowired private IUsuarioRepositorio repositorio; @Override public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException { Usuario encontrado = repositorio.findByNombre(username); List&lt;GrantedAuthority&gt; roles = new ArrayList&lt;&gt;(); roles.add(new SimpleGrantedAuthority(&#34;ADMIN&#34;)); UserDetails userDet = new User(encontrado.getNombre(),encontrado.getClave(),roles); return userDet; } } SecurityConfig.java
@Configuration @EnableWebSecurity public class SecurityConfig extends WebSecurityConfigurerAdapter { @Autowired private UserService userServiceDetails; @Autowired private BCryptPasswordEncoder bcrypt; @Bean public BCryptPasswordEncoder passwordEncoder(){ BCryptPasswordEncoder bCryptPasswordEncoder = new BCryptPasswordEncoder(); return bCryptPasswordEncoder; } @Override protected void configure(AuthenticationManagerBuilder auth) throws Exception { auth.userDetailsService(userServiceDetails).passwordEncoder(bcrypt); } @Override protected void configure(HttpSecurity http) throws Exception { super.configure(http); } } PROYECTO DE EJEMPLO
