Todo lo necesario para implementar un login mediante JPA, utilizando Postgresql como motor de base de datos.
Definir un modelo @Entity public class Usuario { @Id private int id; private String nombre; private String clave; public int getId() { return id; } public void setId(int id) { this.id = id; } public String getNombre() { return nombre; } public void setNombre(String nombre) { this.nombre = nombre; } public String getClave() { return clave; } public void setClave(String clave) { this.clave = clave; } } Crear un repositorio public interface UsuarioRepository extends JpaRepository&lt;Usuario,Integer&gt; { Usuario findByNombre(String nombre); } Servicio de usuarios @Service public class UsuarioService implements UserDetailsService { @Autowired private UsuarioRepository repositorio; @Autowired private BCryptPasswordEncoder encoder; public void crearUsuario() { Usuario usuario = new Usuario(); usuario.setId((int)repositorio.count()+1); usuario.setClave(encoder.encode(&#34;1234&#34;)); usuario.setNombre(&#34;pady&#34;); repositorio.save(usuario); } @Override public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException { Usuario encontrado = repositorio.findByNombre(username); List&lt;GrantedAuthority&gt; roles = new ArrayList&lt;&gt;(); roles.add(new SimpleGrantedAuthority(&#34;ADMIN&#34;)); UserDetails userDet = new User(encontrado.getNombre(),encontrado.getClave(),roles); return userDet; } } Security Config @Configuration @EnableWebSecurity public class SecurityConfig extends WebSecurityConfigurerAdapter { @Autowired private UsuarioService userServiceDetails; @Autowired private BCryptPasswordEncoder bcrypt; @Bean public BCryptPasswordEncoder passwordEncoder(){ BCryptPasswordEncoder bCryptPasswordEncoder = new BCryptPasswordEncoder(); return bCryptPasswordEncoder; } @Override protected void configure(AuthenticationManagerBuilder auth) throws Exception { auth.userDetailsService(userServiceDetails).passwordEncoder(bcrypt); } @Override protected void configure(HttpSecurity http) throws Exception { http .authorizeRequests() .antMatchers(&#34;/&#34;).permitAll() .anyRequest().authenticated() .and() .formLogin() .loginPage(&#34;/login&#34;) .permitAll() .and() .logout() .permitAll(); } } Creación de usuarios @SpringBootTest class PracticaSpringBootApplicationTests { @Autowired private UsuarioService servicio; @Test void contextLoads() { servicio.crearUsuario(); } }
